const WEEK_RE = /week\s+(\d+)/i;
const TOLERANCE = 5; // ignore sub-Ksh5 rounding noise (welfare splits etc.)

function extractWeek(note) {
  const m = WEEK_RE.exec(note || '');
  return m ? Number(m[1]) : null;
}

// Which ContributionType name maps to which ledger column
const TYPE_TO_COLUMN = {
  'Weekly Contribution': 'contribution',
  'Chai': 'chai',
  'Welfare Contribution': null, // welfare liability isn't a simple 1:1 column match, skip
  'Extra Contributions': 'extra',
};

async function main() {
  if (!process.env.MONGO_URI) {
    throw new Error('MONGO_URI is not set.');
  }
  await mongoose.connect(process.env.MONGO_URI);

  const members = await Member.find({}).select('name').lean();
  const memberNameById = new Map(members.map((m) => [String(m._id), m.name]));

  const types = await ContributionType.find({}).select('name').lean();
  const typeNameById = new Map(types.map((t) => [String(t._id), t.name]));

  const contributions = await Contribution.find({ deleted: false }).lean();

  const mismatches = [];
  let checked = 0;

  for (const c of contributions) {
    const week = extractWeek(c.note);
    if (week === null) continue;
    if (!/synchronized from approved workbook/i.test(c.note || '')) continue; // only check the kept (workbook) rows

    const memberName = memberNameById.get(String(c.memberId));
    const typeName = typeNameById.get(String(c.typeId));
    const column = TYPE_TO_COLUMN[typeName];
    if (!memberName || column === undefined || column === null) continue;

    const key = `${memberName}|${week}`;
    const expectedRow = LEDGER_EXPECTED[key];
    if (!expectedRow) continue; // no ledger row for this member/week, skip

    const expectedAmount = expectedRow[column];
    checked += 1;

    if (Math.abs(c.amount - expectedAmount) > TOLERANCE) {
      mismatches.push({
        memberName,
        typeName,
        week,
        dbAmount: c.amount,
        expectedAmount,
        diff: c.amount - expectedAmount,
        id: c._id,
        date: c.date,
      });
    }
  }

  console.log(`Checked ${checked} contributions against the ledger.\n`);

  if (mismatches.length === 0) {
    console.log('No mismatches found.');
    await mongoose.disconnect();
    return;
  }

  mismatches.sort((a, b) => Math.abs(b.diff) - Math.abs(a.diff));

  console.log(`Found ${mismatches.length} mismatched entries:\n`);
  let totalExcess = 0;
  for (const m of mismatches) {
    const dateStr = new Date(m.date).toISOString().slice(0, 10);
    console.log(
      `  ${m.memberName.padEnd(18)} Week ${String(m.week).padStart(2)} ${m.typeName.padEnd(20)} DB=${String(
        m.dbAmount
      ).padStart(7)}  Expected=${String(m.expectedAmount).padStart(7)}  Diff=${String(m.diff).padStart(
        7
      )}  (${dateStr})  id=${m.id}`
    );
    totalExcess += m.diff;
  }

  console.log(`\nTotal excess from these mismatches: Ksh ${totalExcess}`);
  await mongoose.disconnect();
}

main().catch(async (err) => {
  console.error(err);
  await mongoose.disconnect().catch(() => {});
  process.exit(1);
});